import { gunzipSync } from 'node:zlib'
/** Synthetic "This is a speech recognition test", Microsoft Zira, 16 kHz mono PCM; no user audio. */
const pcm = ''
export const AI_TEST_TRANSCRIPT = 'This is a speech recognition test'
export function aiTestAudio(): Buffer {
    const data = gunzipSync(Buffer.from(pcm, 'base64'))
    const wav = Buffer.alloc(44 + data.length)
    wav.write('RIFF'); wav.writeUInt32LE(36 + data.length, 4); wav.write('WAVE', 8)
    wav.write('fmt ', 12); wav.writeUInt32LE(16, 16); wav.writeUInt16LE(1, 20); wav.writeUInt16LE(1, 22)
    wav.writeUInt32LE(16000, 24); wav.writeUInt32LE(32000, 28); wav.writeUInt16LE(2, 32); wav.writeUInt16LE(16, 34)
    wav.write('data', 36); wav.writeUInt32LE(data.length, 40); data.copy(wav, 44)
    return wav
}
